import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { expect, type Page, test as base } from '@playwright/test'

// Generated by global-setup.ts; gitignored.
export const FIXTURE_DIR = fileURLToPath(new URL('.fixtures', import.meta.url))
export const fixture = (name: 'slide' | 'blank' | 'large') => path.join(FIXTURE_DIR, `${name}.png`)

// Every test fails if the page logs a console error or throws.
export const test = base.extend<{ consoleErrors: string[] }>({
  consoleErrors: [
    async ({ page }, use) => {
      const errors: string[] = []
      page.on('console', (msg) => {
        if (msg.type() === 'error') errors.push(msg.text())
      })
      page.on('pageerror', (err) => errors.push(err.message))
      await use(errors)
      expect(errors, 'console errors').toEqual([])
    },
    { auto: true },
  ],
})

export { expect }

// Home → upload screen → pick a file → submit. Returns the job id from the URL.
export async function uploadFromHome(page: Page, file: string) {
  await page.goto('/')
  await page.getByRole('link', { name: 'Analyze a slide' }).click()
  await expect(page).toHaveURL(/\/upload$/)
  await page.locator('input[type="file"]').setInputFiles(file)
  await page.getByRole('button', { name: 'Analyze slide' }).click()
  await expect(page).toHaveURL(/\/jobs\/[0-9a-f]+$/)
  return page.url().split('/').pop()!
}

export const regionBoxes = (page: Page) => page.getByRole('button', { name: /^Region \d/ })
